package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock is the injectable time source used by TokenBucket.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// TokenBucket is a concurrency-safe token bucket.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New returns a TokenBucket allowing up to capacity tokens, refilling at ratePerSecond.
func New(capacity int, ratePerSecond float64, clock Clock) (*TokenBucket, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock is required")
	}
	if capacity <= 0 {
		return nil, errors.New("ratelimit: capacity must be positive")
	}
	if ratePerSecond <= 0 || math.IsNaN(ratePerSecond) || math.IsInf(ratePerSecond, 0) {
		return nil, errors.New("ratelimit: rate must be finite and positive")
	}
	now := clock.Now()
	return &TokenBucket{
		capacity: float64(capacity),
		rate:     ratePerSecond,
		tokens:   float64(capacity),
		last:     now,
		clock:    clock,
	}, nil
}

// NewReal returns a TokenBucket using the system clock.
func NewReal(capacity int, ratePerSecond float64) (*TokenBucket, error) {
	return New(capacity, ratePerSecond, realClock{})
}

// AllowN reports whether n tokens may be consumed, consuming them if so.
// n <= 0 is always allowed and consumes nothing.
func (b *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	if b.tokens >= float64(n) {
		b.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed.
func (b *TokenBucket) Allow() bool { return b.AllowN(1) }

// Tokens returns the current estimated available tokens.
func (b *TokenBucket) Tokens() float64 {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.refillLocked()
	return b.tokens
}

func (b *TokenBucket) refillLocked() {
	now := b.clock.Now()
	if now.Before(b.last) {
		b.last = now
		return
	}
	elapsed := now.Sub(b.last).Seconds()
	if elapsed <= 0 {
		return
	}
	b.tokens += elapsed * b.rate
	if b.tokens > b.capacity {
		b.tokens = b.capacity
	}
	b.last = now
}
