package ratelimit

import (
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu sync.Mutex
	t  time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{t: time.Unix(0, 0)}
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.t
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.t = f.t.Add(d)
}

func TestNewValidation(t *testing.T) {
	clock := newFakeClock()
	cases := []struct {
		name     string
		capacity int
		rate     float64
		clock    Clock
		wantErr  bool
	}{
		{"nil clock", 5, 1, nil, true},
		{"zero capacity", 0, 1, clock, true},
		{"negative capacity", -1, 1, clock, true},
		{"zero rate", 5, 0, clock, true},
		{"negative rate", 5, -1, clock, true},
		{"valid", 5, 1, clock, false},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			b, err := New(tc.capacity, tc.rate, tc.clock)
			if (err != nil) != tc.wantErr {
				t.Fatalf("err = %v, wantErr = %v", err, tc.wantErr)
			}
			if !tc.wantErr && b == nil {
				t.Fatal("expected bucket")
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	type step struct {
		advance time.Duration
		n       int
		want    bool
	}
	cases := []struct {
		name     string
		capacity int
		rate     float64
		steps    []step
	}{
		{"drain and refill", 5, 1, []step{
			{0, 5, true},
			{0, 1, false},
			{2 * time.Second, 2, true},
			{0, 1, false},
		}},
		{"zero and negative", 5, 1, []step{
			{0, 0, true},
			{0, -2, true},
		}},
		{"over capacity", 5, 1, []step{
			{0, 6, false},
		}},
		{"partial refill", 10, 10, []step{
			{0, 10, true},
			{100 * time.Millisecond, 1, true},
			{0, 1, false},
		}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			clock := newFakeClock()
			b, err := New(tc.capacity, tc.rate, clock)
			if err != nil {
				t.Fatal(err)
			}
			for i, s := range tc.steps {
				clock.Advance(s.advance)
				if got := b.AllowN(s.n); got != s.want {
					t.Fatalf("step %d: AllowN(%d) = %v, want %v", i, s.n, got, s.want)
				}
			}
		})
	}
}

func TestAllowNConcurrent(t *testing.T) {
	clock := newFakeClock()
	b, err := New(50, 0.001, clock)
	if err != nil {
		t.Fatal(err)
	}
	var mu sync.Mutex
	allowed := 0
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if b.AllowN(1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed > 50 {
		t.Fatalf("allowed = %d, exceeds capacity 50", allowed)
	}
	if allowed == 0 {
		t.Fatal("expected some allowed requests")
	}
}
